INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1374694-ce261', 'stk-user8890', 'CE 261', 'info', '{"desc": "جودة المقرر بشكل عام\n\nممتازة وفيها نوع الحماس خاصة اللاب .\n\nالمواضيع التي يغطيها المقرر\n\nBasics of Surveying\n\nLeveling\n\nAngles and Directions\n\nTraverse Surveys\n\nTopographic Surveying and Mapping\n\nGeographic Information Systems\n\nالكتاب المستخدم للمقرر\n\nالكتاب للأسف تكون المعلومات بين السطور يبيلك تمعّن القراءة , ومستوى اختبارات الدكتور محمد الصغير للأسف أشوفه أعلى من مستوى الكتاب ! عموما الهوم وورك مفيد لتوصيل المعلومة واحرص تحله .\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nجيدة لكن ليست بمستوى الإختبار برأيي .\n\nمدى فائدته في الناحية التطبيقية\n\nيعلمك سر الأجهزة اللي تشوفها بالشوارع وتدري وش يسوون 😆\n\nتقسيم الدرجات\n\nMidterm Exam : 25%\nHomework, quizzes, and class participation:15%\nLab work (field & exam):20%\nFinal Exam:40%", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-261-surveying-i/120671/8", "user": "user8890", "ts": 1401481154000, "tid": 120671, "pn": 8}}', 1401481154000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1424490-ce261', 'stk-unkhaled', 'CE 261', 'info', '{"desc": "وأما اللآب ف م يحتاج مجهود ذهني , بس تطبّق كلآم المدرس .\nبس تستفيد كثير منه في الميتديرم والفاينل …\nكوزات الصغير واختباراته من الهوم وورك , ويحظر بداية الكلاس ويسجل المتاخرين حتى\nلو بعد نص ساعة ويسمح بالميك آب .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-261-surveying-i/120671/9", "user": "unkhaled", "ts": 1439961583000, "tid": 120671, "pn": 9}}', 1439961583000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492554-ce261', 'stk-_132', 'CE 261', 'info', '{"desc": "كورس يتكلم عن قبل بداية اي مشروع(طريق ، عمارة ، حديقة ،… ) لازم تكون عارف كم مساحة الأرض وكيف مستوى الأرض هل هي مستوية أو مايله وكم يحتاج انه تسوي حفر أو دفن في منطقة معينه من مشروعك .\nالكورس ممتع واحسن شيء خذه بالفرشمن أو اول السفمور لاتأخره (خذه قبل تأخذ CE 215 ) الكورس مافيه بروجيكت.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-261-surveying-i/120671/10", "user": "_132", "ts": 1526526264000, "tid": 120671, "pn": 10}}', 1526526264000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce261', 'stk-user2967', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f98556", "n": "Dr. Nedal Al-Ratrout", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 261 - 092\n\nالتحضير : يمشي ورقه\nطريقة الشرح : ملفات pdf لكنها ممتازه\nالكويزات : يجيب لك سؤال من اخر هوم وورك بس يغير الارقام\nالمياجر: سهله الى متوسطه\nالفاينلات : ^^^\nالقريد النهائي: ممتااز\nالصوت: واضح جدا\nإضافات : فاهم المادد وشرحه كويس\nالدرجات حولها لافرج بدل الستاندر بسبب ان لو بقت ستاندر المعدل العام للقريدات بيرتفع\nوسبب التحويل ع كلامه ان الدكتور اللي يعطيك قريدات مرتفعه كثير مو دكتور او شي زي كذا\n\nوبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p744096-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-nedal-al-ratrout/98556/2", "user": "user2967", "ts": 1292339433000, "tid": 98556, "pn": 2}}]}', 1292339433000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce261', 'stk-civil_engineer1', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f98556", "n": "Dr. Nedal Al-Ratrout", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 261\n\nالتحضير : ورقة تمر\nطريقة الشرح :سلايدات بس ممتاز\nالكويزات :سؤال من اخر هومورك\nالمياجر: سهلة الى متوسطة\nالفاينلات : سهلة الى متوسطة\nالقريد النهائي: B\nالصوت:واضح\nإضافات : الدكتور حبوب بس مو مرة بالقريدات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p940891-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-nedal-al-ratrout/98556/3", "user": "civil_engineer1", "ts": 1322768825000, "tid": 98556, "pn": 3}}]}', 1322768825000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-banyan-ce261', 'stk-banyan', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f98564", "n": "Dr. Hamad Ibrahim Al-Abdul Wahhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 261\n\nالتحضير\nماذكر انه اخذ التحضير ابدا\n\nطريقة الشرح\nاممممم نوعا ما كويس … في بداية السمستر ماكنت افهم عليه لكن مع الوقت صار الوضوع تمام التمام يشرح سلايدات بوربوينت ويستخدم السبورة يومياً في الشرح\n\nمافي كويزات\n\nالمياجر والفاينلات سهلة واغلبها من الهومورك اللي يعطينا ياه بس المشكلة يعطينا هوموركاات تهد الحيل من كثرتهاا\n\nالصوت واضح\n\nاضافات\nاذا شرح حاجه وشافنا ضايعين يسألنا واحد واحد واذا ماحد عرف الجواب يعيد الشرح هع وتقريبا مامرة جاوبت على اسئلته\nاخلاقه فوووق الفوق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p747159-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamad-ibrahim-al-abdul-wahhab/98564/2", "user": "Banyan", "ts": 1292766096000, "tid": 98564, "pn": 2}}]}', 1292766096000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.cool-ce261', 'stk-mr.cool', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f98564", "n": "Dr. Hamad Ibrahim Al-Abdul Wahhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 261 - 111\n\nالتحضير\nفي ورقة تمر على الطلاب لكن ما شفناها إلا كم يوم و بعدها ما صار يحضر .\n\nطريقة الشرح\nيشرح على السبورة و يستخدم سلايدات لعرض الكونسبت ، و يسأل الطلاب و يمر عليهم واحد واحد اسئلة حتى تركز معه .\n\nالكويزات\nطول السمستر كويزين ، سهلة جدا تاخذ فيها دقيقتين بالكثير .\n\nالميدتيرم و الفاينل\nالمادة أصلا سهلة في ما يمكن يعقد في الأسئلة فالاختبارات كانت سهلة معه و أفرج الطلاب في الميدتيرم يمكن 21 من 25 .\n\nالقريد النهائي\na\n\nالصوت\nالكلاس صغير و الصوت واضح جدا\n\nإضافات\nالدكتور أخلاقه عالية و يتعامل معك بكل احترام ، و ما شاء الله عليه الابتسامة طوال السمستر .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970803-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamad-ibrahim-al-abdul-wahhab/98564/3", "user": "Mr.Cool", "ts": 1326953771000, "tid": 98564, "pn": 3}}]}', 1326953771000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8443-ce261', 'stk-user8443', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f98591", "n": "Dr. Khalaf A. Al-Ofi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ce261 ترم 101 وهذي ملاحظاتي وبدون مجاملة :\n\nالتحضير : يوميا لكنه متساهل جدا من ناحية التأخير ممكن انه يحضرك آخر 10 دقايق\n\nطريقة الشرح : السبورة ويعرض سلايدات\n\nالكويزات : لا يوجد\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: c\n\nالصوت: منخفض ويجيب النوم\n\nإضافات : الدكتور طيب وحبوب لكن من ناحية الشرح هو يجتهد بايصال الفكرة ويجاوب على الاسئلة بصدر\n\nرحب لكن اعتقد انه ما يوصل المعلومة جيدا… بالنهاية حاول انك ما تنزل معه واذا نزلت معه ما اعتقد انك\n\nبتواجه مشكلة لان المادة سهلة وما فيها تعقيد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891632-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-khalaf-a-al-ofi/98591/3", "user": "user8443", "ts": 1314231940000, "tid": 98591, "pn": 3}}, {"id": "stk-dr-f98580", "n": "Dr. Mirza Ghouse Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت معه لاب ce261 ترم 101 :\n\nالتحضير : التحضير في كل لاب منه هو ومن اللي معك بالقروب\n\nطريقة الشرح : يشرح اول شئ التجربة بالكلاس باستخدام السبورة احيانا وبعض الاحيان يكون ما فيه لاب عملي يكون فيه توضيح لبعض مواضيع الكورس باستخدام السلايدات… بالنسبة لشرح اللاب نفسه لا بأس ويتساعد معك اذا سألته عن اي شئ لكن اذا طلعت تطبق بيكون معك اثنين مساعدين مصري حبوب مرره اسمه على ما اعتقد صُبح وهندي وكلهم يساعدونك وحبوبين يعني ما عليك اي شئ يشكل عليك اسئلهم\n\nالكويزات : اذكراني سمعت من اللي نزلوا معه كلاس ان كويزاته تقريبا صعبة\n\nالمياجر: كومن وهو ميدتيرم واحد\n\nالفاينلات : الاختبار بالنسبة للاب جزئين نظري وعملي… النظري اذكر انه عطانا اختبار متوسط الصعوبة والعملي على حسب فهمك خلال الترم لكن العملي كان واضح ما جاب شئ صعب\n\nالقريد النهائي: b\n\nالصوت: واضح\n\nإضافات : الدكتور حبوب واعتقد انك ماراح تواجه اشكاليه اذا نزلت معه لكن على ما اظن ومن اللي اسمعه\n\nان الافضل في هالكورس هذا هو الدكتور عبدالوهاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891642-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mirza-ghouse-baig/98580/8", "user": "user8443", "ts": 1314233074000, "tid": 98580, "pn": 8}}]}', 1314231940000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-houri-ce261', 'stk-al-houri', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f152673", "n": "Dr. Mohammed A. Al-Sughaiyer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 261 - Term 162\n\n١)- التحضير :\nيحضر في بداية كل محاضرة بمناداة الأسماء وأي شخص يأتي بعد التحضير يكون متأخراً - يسمح بالميك أب\n\n٢)- طريقة الشرح :\nيشرح بواسطة السلايدات ( يقرأ تقريباً ) وإذا كان هناك نقطة تحتاج إلى التوضيح يستخدم السبورة\n\n٣)- الكويزات :\nيعطي كويزات بعد كل فصل ننهيه في المنهج وتكون مشابه للواجبات - أعطانا ٣ كويزات - سهلة إلى متوسطة\n\n٤)- المياجر:\nمتوسطة الصعوبة تأتي مشابه للواجبات - تصحيحه عادل\n\n٥)- الفاينلات :\nمتوسطة الصعوبة مشابه للواجبات\n\n٦)- الصوت:\nمتوسط العلو قريب إلى الهدوء - لغته الإنجليزية جيدة بعض الشيء\n\n٧)- إضافات :\n- الدكتور متساهل في أوقات تسليم الواجبات\n- يعطي واجبات بعد كل فصل ننهيه\n- تقدر تختبر الكويز مع سكشن غير سكشنك\n- ينزل سلايداته والسيلابس والواجبات في البلاك بورد ( لكن لم ينزل أجوبة الواجبات )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473794-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-a-al-sughaiyer/152673/4", "user": "Al-Houri", "ts": 1495658779000, "tid": 152673, "pn": 4}}]}', 1495658779000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh1417_2015-ce261', 'stk-saleh1417_2015', 'CE 261', 'doc', '{"docs": [{"id": "stk-dr-f176817", "n": "Dr. Imran Reza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab CE261-162\n\nالتحضير :\nيحضر بداية اللاب وماعنده مشكلة تتأخر ١٠د إلى ١٥ د بس لاتفلها عاد :speech_balloon: .\n\nطريقة الشرح :\n\nيشرح التجربة بشكل عام على السبورة ويكتب القوانين وبعدين نطلع للساحة اللي عند مبنى واحد عشان نسوي التجربة بعدين نرجع نسوي الريبورت يعطينا سامبلز لريبورتات سابقة وحنا نحذو حذوهم 😁.\n\nالكويزات :\n\nمافيه عنده بري لاب طووول الترم فيه كويز واحد بس ويكون بعد مايشرح الدرس يعطيك اياه \" ويقول مااسميه كويز اسميه exrcise \" لكن عنده تقريبا ٤ هوموركات لكل قروب ف حاول تقسم الشغل بينك وبين الشباب\n\nالمياجر: كومن\n\nالفاينلات :\n\nفيه عنده فاينل لاب وعليه نسبة كبيرة 8% من الكورس وباقي الشغل 12% .\n\nالقريد النهائي:\n\nبالنسبة لي اعطيه A+ وانا مااشوف الدرب يستااااهل الصراحة.\n\nالصوت: لهجة هندية لكن راح تتعود عليها .\n\nإضافات :\n\nانساان طيوب ويساعدك باللي يقدر عليه يسمح بالميك اب مرات اذا عندك ظروف مع انه شغل قروبات لكن مخلي الوضع سهالات الله يفتحها بوجهه وييسر اموره … نصيحتي لك سجل عنده وانت مغمممممممممممممضض خطييييير تعامل + درجات 👍 👍 👍 لكن لاتقعد تغيب وتحط اللوم عليه :ninja:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474242-ce261", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/imran-reza/176817/2", "user": "Saleh1417_2015", "ts": 1496242729000, "tid": 176817, "pn": 2}}]}', 1496242729000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
